#!/usr/bin/env python3
"""Decode stack strings from version.dll: plaintext = (ciphertext ^ 0x0a) + 0x0c"""
import re, subprocess

asm = open('/home/ctfplayer/workspace/vdll.asm').read().splitlines()
imms = []
for line in asm:
    m = re.match(r'\s+([0-9a-f]+):\t(.*)', line)
    if not m: continue
    va = int(m.group(1),16)
    ins = m.group(2).split('#')[0].strip()
    mm = re.match(r'(mov[lwb])\s+\$0x([0-9a-f]+),\s*[-0-9a-fx]+\((%rbp|%rsp)\)', ins)
    if mm:
        mn, val = mm.group(1), int(mm.group(2),16)
        size = {'movl':4,'movw':2,'movb':1}[mn]
        imms.append((va,size,val))

def dec(b):
    return bytes(((x ^ 0x0a) + 0x0c) & 0xff for x in b)

runs = []
i = 0
while i < len(imms):
    va,size,val = imms[i]
    run = [(va,size,val)]
    j = i+1
    while j < len(imms):
        va2,size2,val2 = imms[j]
        if va2 - run[-1][0] <= 0x30 and size2==size:
            run.append(imms[j]); j+=1
        else:
            break
    if len(run) >= 2:
        runs.append(run)
    i = j

for run in runs:
    blob = b''
    for va,size,val in run:
        blob += val.to_bytes(size,'little')
    d = dec(blob)
    printable = ''.join(chr(c) if 32<=c<127 else '.' for c in d)
    print(f"--- run @ {run[0][0]:x} ({len(run)} imms, {len(blob)}B) ---")
    print("txt:", printable)

